from pathlib import Path
p=Path('src/components/Coverflow.svelte');s=p.read_text(encoding='utf-8-sig')
s=s.replace('<script>',"<script>\n import {onMount} from 'svelte';import {createQuickSelection} from '../coverflow-selection';",1)
s=s.replace('let accumulator=0;', "let accumulator=0;let hovered=false,root,spaceHeld=$state(false);\n const quick=createQuickSelection({getIds:()=>list.map(a=>a.id),getCurrent:()=>studio.aid,toggle,add:ids=>{studio.selected=[...new Set([...studio.selected,...ids])];studio.batchScope='auto';},navigate:select,onHeld:value=>spaceHeld=value});\n function typing(){const el=document.activeElement;return !!el&&(el.isContentEditable||!!el.closest('input,textarea,select,[role=textbox]'));}\n function available(){return hovered&&!typing()&&!studio.busy&&!studio.modal&&!studio.confirm&&!layout.coverflowCollapsed&&studio.mode==='edit'&&studio.view==='canvas';}\n function release(){quick.release();accumulator=0;}\n function keyDown(e){if(e.code==='Escape'){release();return;}if(e.code!=='Space'||e.ctrlKey||e.altKey||e.metaKey||e.isComposing||!available())return;e.preventDefault();e.stopPropagation();if(!e.repeat)quick.press();}\n function keyUp(e){if(e.code!=='Space'||!quick.held)return;e.preventDefault();e.stopPropagation();release();}\n onMount(()=>{window.addEventListener('keydown',keyDown,true);window.addEventListener('keyup',keyUp,true);window.addEventListener('blur',release);const hide=()=>{if(document.hidden)release();};document.addEventListener('visibilitychange',hide);return()=>{window.removeEventListener('keydown',keyDown,true);window.removeEventListener('keyup',keyUp,true);window.removeEventListener('blur',release);document.removeEventListener('visibilitychange',hide);release();};});\n $effect(()=>{studio.pid;if(studio.busy||studio.modal||studio.confirm||layout.coverflowCollapsed)release();});")
old="function wheel(e){e.preventDefault();accumulator+=e.deltaY||e.deltaX;if(accumulator>35){next();accumulator=0;}else if(accumulator< -35){previous();accumulator=0;}}"
new="function wheel(e){if(studio.busy||studio.modal||studio.confirm||layout.coverflowCollapsed){release();return;}e.preventDefault();const delta=e.deltaY||e.deltaX;if(quick.held){if(!available()){release();return;}quick.wheel(delta*(e.deltaMode===1?16:e.deltaMode===2?240:1));return;}accumulator+=delta;if(accumulator>35){next();accumulator=0;}else if(accumulator< -35){previous();accumulator=0;}}"
assert old in s;s=s.replace(old,new)
s=s.replace('<section class="cf-root"', '<section bind:this={root} class="cf-root" class:quick-selecting={spaceHeld} onpointerenter={e=>{hovered=e.pointerType!==\'touch\';}} onpointerleave={()=>{hovered=false;release();}} onpointercancel={()=>{hovered=false;release();}}')
s=s.replace('aria-label="Coverflow"', 'aria-label="Coverflow" title="Space: toggle current image · Hold Space + scroll: select images"')
s=s.replace('<div class="cf-footer">','<div class="cf-footer">{#if spaceHeld}<span class="cf-quick-hint" role="status">Selecting · release Space to stop</span>{/if}')
p.write_text(s,encoding='utf-8')
